    enonce: "المستقيم (OF) يقطع (DE) في J<br>بيّن أنّ الرباعي CODJ معيّن ثمّ أحسب مساحته",
    correction: [{"quoi":"القاعدة","math":"رباعي قطراه يتناصفان و أضلاعه المتجاورة متقايسة هو معيّن"},{"quoi":"في المستطيل، نصفا القطرين متقايسان","math":"<span dir=\"ltr\" class=\"expr\">CO = 3</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">OD = 3</span>"},{"quoi":"نتحقّق من الضلعين الآخرين","math":"<span dir=\"ltr\" class=\"expr\">DJ = 3</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">JC = 3</span>"},{"quoi":"نحسب القطر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">CD = 2<span class=\"rad\"><span class=\"rcd\">6</span></span></span>"},{"quoi":"و القطر الثاني","math":"<span dir=\"ltr\" class=\"expr\">OJ = 2<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"نحسب المساحة","math":"<span dir=\"ltr\" class=\"expr\">2<span class=\"rad\"><span class=\"rcd\">6</span></span> × <span class=\"frac\"><span class=\"num\">2<span class=\"rad\"><span class=\"rcd\">3</span></span></span><span class=\"den\">2</span></span> = 6<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"النتيجة","math":"الرباعي CODJ معيّن، و مساحته <span dir=\"ltr\" class=\"expr\">6<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"}],
