    enonce: "أوجد حصرا مداه <span dir=\"ltr\" class=\"expr\">10^-1</span> لكلّ من <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">3</span></span></span>",
